// The shape of a comment, as the API sends it. The comments themselves live
// in Laravel (generated by scripts/data/extras.mjs); see src/api/discussion.ts.

import type { ChatTier } from './chat'
import type { Vote } from '@/types/content'

export interface Comment {
  id: string
  user: string
  tier: ChatTier
  /** ISO 8601 date string. */
  postedAt: string
  text: string
  likes: number
  dislikes: number
  replies: Comment[]
  /** Posted by the viewer. */
  mine?: boolean
  /** The viewer's own vote, saved on their account (Laravel mode). */
  myVote?: Vote
}

/** Total comments in a thread, replies included. */
export function countComments(comments: Comment[]): number {
  return comments.reduce((total, c) => total + 1 + c.replies.length, 0)
}
